    public void display(String data) {
        System.out.println("View: " + data);
    }
}

class Controller {
    private Model model;
    private View view;
    public Controller(Model m, View v) {
        model = m;
        view = v;
    }
    public void updateView() {
        view.display(model.getData());
    }
}

